     1→/**
     2→ * VideoPlayerView — expo-video player for a single viewer slide.
     3→ *
     4→ * ── WHY THIS COMPONENT EXISTS ────────────────────────────────────────────────
     5→ * key={displayUri} in the parent forces a completely fresh player (and fresh
     6→ * useVideoPlayer hook) for every new file:// URI.  That avoids stale-player
     7→ * state across slides.
     8→ *
     9→ * ── ANDROID 11+ OEM SURFACE BUG ─────────────────────────────────────────────
    10→ * On many Android 11+ OEM builds (Samsung, Xiaomi, Realme, Oppo …) the
    11→ * SurfaceTexture that expo-video creates for the VideoView can briefly detach
    12→ * and reattach during the first GPU layout pass.  ExoPlayer reacts to the
    13→ * detach by pausing itself (playingChange → isPlaying:false) and then does NOT
    14→ * auto-resume when the surface reattaches.  This is the "plays 1 ms then
    15→ * freezes" report: one frame renders, surface detaches, ExoPlayer freezes.
    16→ *
    17→ * THREE-LAYER DEFENCE:
    18→ *
    19→ *   1. timeUpdate  — fires every 250 ms whenever frames are advancing.
    20→ *      currentTime > 0  means real rendering is happening → confirmPlaying().
    21→ *      This is the most reliable cross-OEM signal.
    22→ *
    23→ *   2. playingChange → isPlaying:false recovery
    24→ *      If the video WAS confirmed playing and then stops unexpectedly while the
    25→ *      slide is still active, we force-resume after 80 ms (surface reattach
    26→ *      window).  This directly cancels the OEM freeze.
    27→ *
    28→ *   3. Nudge schedule — calls player.play() at [50, 200, 500, 1000, 1800, 3000]
    29→ *      ms after mount.  Handles OEMs where the surface attaches AFTER
    30→ *      readyToPlay fires.  Nudges stop the moment confirmPlaying() is called.
    31→ *
    32→ * ── SWIPE-BACK FIX ───────────────────────────────────────────────────────────
    33→ * When isActive flips true→false (swipe away) the parent resets thumbnailOpacity
    34→ * to 1.  When the user swipes back (false→true), we reset hasCalledOnPlaying so
    35→ * onPlaying() can fire again, fading the thumbnail out once more.
    36→ */
    37→import React, { useEffect, useRef, useCallback } from 'react';
    38→import { StyleSheet } from 'react-native';
    39→import { VideoView, useVideoPlayer } from 'expo-video';
    40→
    41→interface VideoPlayerViewProps {
    42→  fileUri: string;
    43→  isActive: boolean;
    44→  onPlaying: () => void;
    45→  onError: (message: string) => void;
    46→}
    47→
    48→export function VideoPlayerView({
    49→  fileUri,
    50→  isActive,
    51→  onPlaying,
    52→  onError,
    53→}: VideoPlayerViewProps) {
    54→  const isActiveRef = useRef(isActive);
    55→  isActiveRef.current = isActive;
    56→
    57→  const hasCalledOnPlaying = useRef(false);
    58→  const nudgeTimers = useRef<ReturnType<typeof setTimeout>[]>([]);
    59→
    60→  const player = useVideoPlayer({ uri: fileUri }, (p) => {
    61→    p.loop = true;
    62→    p.muted = false;
    63→    // timeUpdate fires every 250 ms ONLY when frames are actually advancing.
    64→    // This is our most reliable "video is truly playing" signal.
    65→    p.timeUpdateEventInterval = 0.25;
    66→    // Set playWhenReady=true immediately — ExoPlayer will start as soon as the
    67→    // surface attaches, without needing a second play() call from JS.
    68→    p.play();
    69→  });
    70→
    71→  const clearNudges = () => {
    72→    nudgeTimers.current.forEach(clearTimeout);
    73→    nudgeTimers.current = [];
    74→  };
    75→
    76→  // Stable callback — safe to capture in the [] effect.
    77→  const confirmPlaying = useCallback(() => {
    78→    if (hasCalledOnPlaying.current) return;
    79→    hasCalledOnPlaying.current = true;
    80→    clearNudges();
    81→    onPlaying();
    82→  }, [onPlaying]); // eslint-disable-line react-hooks/exhaustive-deps
    83→
    84→  useEffect(() => {
    85→    // ── Layer 1: timeUpdate ───────────────────────────────────────────────────
    86→    // currentTime > 0 means ExoPlayer IS rendering frames to the screen.
    87→    const timeUpdateSub = player.addListener('timeUpdate', (event: any) => {
    88→      if ((event.currentTime ?? 0) > 0) confirmPlaying();
    89→    });
    90→
    91→    // ── Layer 2: playingChange ────────────────────────────────────────────────
    92→    // • isPlaying: true  → backup confirmation (some OEMs skip timeUpdate)
    93→    // • isPlaying: false → RECOVERY: if video was confirmed playing but stopped
    94→    //   while the slide is still active, force-resume after 80 ms.
    95→    //   This is the direct fix for the Android 11+ OEM surface-detach freeze.
    96→    const playingSub = player.addListener('playingChange', (event: any) => {
    97→      if (event.isPlaying) {
    98→        confirmPlaying();
    99→      } else if (hasCalledOnPlaying.current && isActiveRef.current) {
   100→        // Unexpected stop while slide is active — surface probably detached.
   101→        // Wait 80 ms for the GPU compositor to reattach it, then resume.
   102→        setTimeout(() => {
   103→          if (isActiveRef.current) {
   104→            try { player.play(); } catch {}
   105→          }
   106→        }, 80);
   107→      }
   108→    });
   109→
   110→    const statusSub = player.addListener('statusChange', (event: any) => {
   111→      if (event.status === 'error') {
   112→        clearNudges();
   113→        onError(event.error?.message ?? 'Playback error');
   114→      }
   115→    });
   116→
   117→    // Fast path: player already playing before our listeners attached.
   118→    if ((player as any).playing) {
   119→      confirmPlaying();
   120→    }
   121→
   122→    // ── Layer 3: nudge schedule ───────────────────────────────────────────────
   123→    // SurfaceView attachment on Android can lag behind readyToPlay by hundreds
   124→    // of ms.  We fire play() at escalating delays so we hit the moment the
   125→    // surface IS ready.  Stops immediately when confirmPlaying() fires.
   126→    const nudgeDelays = [50, 200, 500, 1000, 1800, 3000];
   127→    nudgeTimers.current = nudgeDelays.map((delay) =>
   128→      setTimeout(() => {
   129→        if (!hasCalledOnPlaying.current && isActiveRef.current) {
   130→          try { player.play(); } catch {}
   131→        }
   132→      }, delay),
   133→    );
   134→
   135→    return () => {
   136→      timeUpdateSub.remove();
   137→      playingSub.remove();
   138→      statusSub.remove();
   139→      clearNudges();
   140→      try { player.release(); } catch {}
   141→    };
   142→  }, []); // eslint-disable-line react-hooks/exhaustive-deps
   143→
   144→  // ── Pause / resume + swipe-back reset ────────────────────────────────────
   145→  // When isActive goes true→false: pause (parent also resets thumbnailOpacity→1).
   146→  // When isActive goes false→true: reset hasCalledOnPlaying so onPlaying() fires
   147→  // again, which fades the thumbnail back out.
   148→  useEffect(() => {
   149→    try {
   150→      if (isActive) {
   151→        // Allow onPlaying() to fire again after a swipe-back so the thumbnail
   152→        // fades correctly on resume (parent reset opacity to 1 on inactive).
   153→        hasCalledOnPlaying.current = false;
   154→        player.play();
   155→      } else {
   156→        player.pause();
   157→      }
   158→    } catch {}
   159→  }, [isActive]); // eslint-disable-line react-hooks/exhaustive-deps
   160→
   161→  return (
   162→    <VideoView
   163→      player={player}
   164→      style={StyleSheet.absoluteFill}
   165→      nativeControls={false}
   166→      contentFit="contain"
   167→    />
   168→  );
   169→}
