     1→/**
     2→ * ExoPlayer — JS wrapper for the native Media3/ExoPlayer view module.
     3→ *
     4→ * CONTRACT: fileUri MUST be a file:// URI. The native layer emits
     5→ * onPlayerError immediately if a non-file:// URI is passed.
     6→ * Always use SafReaderModule.copyFileToCache() before calling this.
     7→ *
     8→ * Available only on Android custom dev-client / EAS builds (native module).
     9→ * Returns null on iOS and web.
    10→ *
    11→ * WHY requireNativeComponent without UIManager.getViewManagerConfig:
    12→ * UIManager.getViewManagerConfig is unreliable in Fabric (new arch) — it may
    13→ * return null even when the view manager IS compiled and registered, because
    14→ * Fabric uses its own view config registry that is populated differently from
    15→ * UIManager. requireNativeComponent is the correct entry point; it delegates
    16→ * to NativeComponentRegistry internally. If the native view is absent at
    17→ * render time, Fabric throws "View config not found" — that error is caught
    18→ * by the ExoPlayerBoundary in ViewerItem (not by this module).
    19→ */
    20→import React from 'react';
    21→import {
    22→  requireNativeComponent,
    23→  Platform,
    24→  ViewStyle,
    25→  NativeSyntheticEvent,
    26→} from 'react-native';
    27→
    28→// ── Native component shape (matches ExoPlayerViewManager props/events) ────────
    29→
    30→interface NativeExoPlayerProps {
    31→  fileUri: string;
    32→  paused?: boolean;
    33→  muted?: boolean;
    34→  style?: ViewStyle;
    35→  onPlayerReady?: (event: NativeSyntheticEvent<Record<string, never>>) => void;
    36→  onPlayerError?: (event: NativeSyntheticEvent<{ error: string }>) => void;
    37→}
    38→
    39→// requireNativeComponent does NOT verify the native side at module load time —
    40→// it creates a component class that delegates to the registered view manager.
    41→// Absence of the native view manager is only detected at first render (Fabric
    42→// throws "View config not found"). ExoPlayerBoundary in ViewerItem catches that.
    43→let NativeExoPlayerView: ReturnType<typeof requireNativeComponent<NativeExoPlayerProps>> | null = null;
    44→if (Platform.OS === 'android') {
    45→  try {
    46→    NativeExoPlayerView = requireNativeComponent<NativeExoPlayerProps>('ExoPlayerView');
    47→  } catch {
    48→    // requireNativeComponent should not throw at module level, but guard anyway.
    49→    NativeExoPlayerView = null;
    50→  }
    51→}
    52→
    53→// ── Public JS interface ───────────────────────────────────────────────────────
    54→
    55→export interface ExoPlayerViewProps {
    56→  /** Must be a file:// URI — never content://. Copy SAF URIs first. */
    57→  fileUri: string;
    58→  paused?: boolean;
    59→  muted?: boolean;
    60→  style?: ViewStyle;
    61→  onPlayerReady?: () => void;
    62→  onPlayerError?: (error: string) => void;
    63→}
    64→
    65→export function ExoPlayerView({
    66→  fileUri,
    67→  paused = false,
    68→  muted = false,
    69→  style,
    70→  onPlayerReady,
    71→  onPlayerError,
    72→}: ExoPlayerViewProps): React.ReactElement | null {
    73→  if (!NativeExoPlayerView) return null;
    74→
    75→  return React.createElement(NativeExoPlayerView, {
    76→    fileUri,
    77→    paused,
    78→    muted,
    79→    style,
    80→    onPlayerReady: onPlayerReady
    81→      ? (_e: NativeSyntheticEvent<Record<string, never>>) => onPlayerReady()
    82→      : undefined,
    83→    onPlayerError: onPlayerError
    84→      ? (e: NativeSyntheticEvent<{ error: string }>) =>
    85→          onPlayerError(e.nativeEvent?.error ?? 'Playback error')
    86→      : undefined,
    87→  });
    88→}
    89→
    90→/**
    91→ * True on Android where requireNativeComponent succeeded at module load time.
    92→ * Does NOT guarantee the native view manager is compiled — use ExoPlayerBoundary
    93→ * to catch render-time failures gracefully.
    94→ */
    95→export function isAvailable(): boolean {
    96→  return NativeExoPlayerView !== null;
    97→}
