   224→        () => { savedTranslateX.value = translateX.value; },
   225→      );
   226→      translateY.value = withDecay(
   227→        { velocity: e.velocityY * 0.5, deceleration: 0.92, clamp: [-maxY, maxY] },
   228→        () => { savedTranslateY.value = translateY.value; },
   229→      );
   230→    });
