    49→  fileUri,
    50→  isActive,
    51→  onPlaying,
    52→  onError,
    53→}: VideoPlayerViewProps) {
    54→  const isActiveRef = useRef(isActive);
    55→  isActiveRef.current = isActive;
    56→
    57→  const hasCalledOnPlaying = useRef(false);
    58→  // Pending recovery timer.  Strategy: when isPlaying:false fires, we do NOT
    59→  // immediately call player.play() — instead we wait 300 ms to see if ExoPlayer
    60→  // self-recovers (normal buffering refill).  If isPlaying:true fires within
    61→  // those 300 ms we cancel the timer (no-op).  If the player is STILL stopped
    62→  // after 300 ms it is a genuine freeze (surface detach / OEM GPU stall) and we
    63→  // force-resume.  This prevents both:
    64→  //   • immediate recovery → buffering → recovery → loop  (old 80 ms behaviour)
    65→  //   • 4-second gap → user sees a 3-second hard freeze  (previous fix)
    66→  const recoveryTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
    67→  const nudgeTimers = useRef<ReturnType<typeof setTimeout>[]>([]);
    68→
    69→  const player = useVideoPlayer({ uri: fileUri }, (p) => {
    70→    p.loop = true;
