package expo.modules.exoplayer;

import android.content.Context;
import android.graphics.SurfaceTexture;
import android.net.Uri;
import android.view.Surface;
import android.view.TextureView;
import android.view.ViewGroup;
import android.widget.FrameLayout;

import androidx.annotation.NonNull;
import androidx.media3.common.AudioAttributes;
import androidx.media3.common.C;
import androidx.media3.common.MediaItem;
import androidx.media3.common.PlaybackException;
import androidx.media3.common.Player;
import androidx.media3.exoplayer.DefaultLoadControl;
import androidx.media3.exoplayer.ExoPlayer;

import com.facebook.react.bridge.Arguments;
import com.facebook.react.bridge.ReactContext;
import com.facebook.react.bridge.WritableMap;
import com.facebook.react.uimanager.events.RCTEventEmitter;

/**
 * TextureView-based ExoPlayer wrapper.
 *
 * WHY TextureView INSTEAD OF SurfaceView:
 * expo-video uses PlayerView which defaults to SurfaceView on Android.
 * SurfaceView renders via a separate hardware overlay that can be
 * destroyed and recreated independently of the View hierarchy. On
 * Android 11+ OEM builds (Samsung, Xiaomi, Realme, Oppo …) the GPU
 * compositor occasionally destroys and does NOT recreate the surface
 * during a layout pass, leaving ExoPlayer frozen on the last frame.
 *
 * TextureView renders into the normal View layer (as a hardware-
 * accelerated canvas), so its surface is owned by the View system and
 * is NEVER destroyed while the View is attached. This eliminates the
 * freeze-on-OEM-surface-detach class of bugs entirely.
 *
 * BUFFER SIZING:
 * Default ExoPlayer buffers are tuned for streaming. For local file://
 * playback on Android storage (fast sequential read) we use a smaller
 * minBuffer (500 ms) so playback starts quickly, and a 30-second max
 * so the decoder has plenty of frames pre-decoded. bufferForPlayback
 * is 250 ms — enough to absorb an IO spike without stalling.
 */
public class ExoPlayerView extends FrameLayout {

    private ExoPlayer player;
    private final TextureView textureView;
    private Surface activeSurface;
    private String pendingUri;
    private boolean paused = false;
    private boolean muted = false;
    private boolean surfaceReady = false;

    public ExoPlayerView(@NonNull Context context) {
        super(context);

        textureView = new TextureView(context);
        textureView.setLayoutParams(new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.MATCH_PARENT
        ));
        addView(textureView);

        textureView.setSurfaceTextureListener(new TextureView.SurfaceTextureListener() {
            @Override
            public void onSurfaceTextureAvailable(@NonNull SurfaceTexture st, int w, int h) {
                surfaceReady = true;
                activeSurface = new Surface(st);
                if (player != null) {
                    player.setVideoSurface(activeSurface);
                    if (!paused) player.play();
                } else if (pendingUri != null) {
                    buildPlayer(context, pendingUri);
                }
            }

            @Override
            public void onSurfaceTextureSizeChanged(@NonNull SurfaceTexture st, int w, int h) {
                // TextureView handles resize internally — no action needed.
            }

            @Override
            public boolean onSurfaceTextureDestroyed(@NonNull SurfaceTexture st) {
                // Return false: we keep the SurfaceTexture alive by not releasing it.
                // This prevents ExoPlayer from losing its surface during brief
                // parent-view re-layouts (e.g. status bar hide/show transitions).
                surfaceReady = false;
                if (player != null) player.clearVideoSurface();
                if (activeSurface != null) {
                    activeSurface.release();
                    activeSurface = null;
                }
                return true;
            }

            @Override
            public void onSurfaceTextureUpdated(@NonNull SurfaceTexture st) {
                // Called every frame — nothing to do here.
            }
        });
    }

    // ── Called by ViewManager when the `fileUri` prop changes ─────────────────

    public void setFileUri(String uri) {
        if (uri == null || uri.isEmpty()) return;
        // Release previous player before building a new one.
        releasePlayer();
        pendingUri = uri;
        if (surfaceReady) {
            buildPlayer(getContext(), uri);
        }
        // If surface not yet ready, buildPlayer() will be called from
        // onSurfaceTextureAvailable once the TextureView is laid out.
    }

    public void setPaused(boolean paused) {
        this.paused = paused;
        if (player == null) return;
        if (paused) {
            player.pause();
        } else if (surfaceReady) {
            player.play();
        }
    }

    public void setMuted(boolean muted) {
        this.muted = muted;
        if (player != null) player.setVolume(muted ? 0f : 1f);
    }

    // ── Internal ──────────────────────────────────────────────────────────────

    private void buildPlayer(Context context, String uri) {
        // Optimised load control for local file:// playback.
        DefaultLoadControl loadControl = new DefaultLoadControl.Builder()
                .setBufferDurationsMs(
                        500,     // minBufferMs  — start fast from local storage
                        30_000,  // maxBufferMs  — keep 30 s pre-decoded
                        250,     // bufferForPlaybackMs
                        500      // bufferForPlaybackAfterRebufferMs
                )
                .build();

        // Declare media intent to Android so audio routing is correct.
        AudioAttributes audioAttrs = new AudioAttributes.Builder()
                .setUsage(C.USAGE_MEDIA)
                .setContentType(C.AUDIO_CONTENT_TYPE_MOVIE)
                .build();

        player = new ExoPlayer.Builder(context)
                .setLoadControl(loadControl)
                .build();

        player.setAudioAttributes(audioAttrs, /* handleAudioFocus= */ true);
        // Pause when headphones are unplugged (audio-becoming-noisy).
        player.setHandleAudioBecomingNoisy(true);
        player.setRepeatMode(Player.REPEAT_MODE_ONE);
        player.setVolume(muted ? 0f : 1f);

        if (activeSurface != null && activeSurface.isValid()) {
            player.setVideoSurface(activeSurface);
        }

        player.addListener(new Player.Listener() {
            @Override
            public void onPlaybackStateChanged(int state) {
                if (state == Player.STATE_READY) {
                    emit("onPlayerReady", Arguments.createMap());
                    if (!paused && surfaceReady) player.play();
                }
            }

            @Override
            public void onPlayerError(@NonNull PlaybackException error) {
                WritableMap payload = Arguments.createMap();
                String msg = error.getMessage();
                payload.putString("error", msg != null ? msg : "ExoPlayer error");
                emit("onPlayerError", payload);
            }
        });

        player.setMediaItem(MediaItem.fromUri(Uri.parse(uri)));
        player.prepare();
        if (!paused && surfaceReady) player.play();
    }

    private void releasePlayer() {
        if (player != null) {
            player.release();
            player = null;
        }
    }

    private void emit(String eventName, WritableMap payload) {
        ReactContext ctx = (ReactContext) getContext();
        ctx.getJSModule(RCTEventEmitter.class).receiveEvent(getId(), eventName, payload);
    }

    @Override
    protected void onDetachedFromWindow() {
        super.onDetachedFromWindow();
        releasePlayer();
        if (activeSurface != null) {
            activeSurface.release();
            activeSurface = null;
        }
    }
}

package expo.modules.exoplayer;

import androidx.annotation.NonNull;

import com.facebook.react.uimanager.SimpleViewManager;
import com.facebook.react.uimanager.ThemedReactContext;
import com.facebook.react.uimanager.annotations.ReactProp;

import java.util.HashMap;
import java.util.Map;

public class ExoPlayerViewManager extends SimpleViewManager<ExoPlayerView> {

    public static final String REACT_CLASS = "ExoPlayerView";

    @NonNull
    @Override
    public String getName() {
        return REACT_CLASS;
    }

    @NonNull
    @Override
    protected ExoPlayerView createViewInstance(@NonNull ThemedReactContext context) {
        return new ExoPlayerView(context);
    }

    @ReactProp(name = "fileUri")
    public void setFileUri(ExoPlayerView view, String fileUri) {
        view.setFileUri(fileUri);
    }

    @ReactProp(name = "paused", defaultBoolean = false)
    public void setPaused(ExoPlayerView view, boolean paused) {
        view.setPaused(paused);
    }

    @ReactProp(name = "muted", defaultBoolean = false)
    public void setMuted(ExoPlayerView view, boolean muted) {
        view.setMuted(muted);
    }

    @Override
    public Map<String, Object> getExportedCustomDirectEventTypeConstants() {
        Map<String, Object> events = new HashMap<>();
        Map<String, String> ready = new HashMap<>();
        ready.put("registrationName", "onPlayerReady");
        events.put("onPlayerReady", ready);
        Map<String, String> error = new HashMap<>();
        error.put("registrationName", "onPlayerError");
        events.put("onPlayerError", error);
        return events;
    }
}

package expo.modules.exoplayer;

import com.facebook.react.bridge.ReactApplicationContext;
import com.facebook.react.bridge.ReactContextBaseJavaModule;

public class ExoPlayerModule extends ReactContextBaseJavaModule {
    public ExoPlayerModule(ReactApplicationContext context) {
        super(context);
    }

    @Override
    public String getName() {
        return "ExoPlayerModule";
    }
}

package expo.modules.exoplayer;

import com.facebook.react.ReactPackage;
import com.facebook.react.bridge.NativeModule;
import com.facebook.react.bridge.ReactApplicationContext;
import com.facebook.react.uimanager.ViewManager;

import java.util.Arrays;
import java.util.List;

public class ExoPlayerPackage implements ReactPackage {
    @Override
    public List<NativeModule> createNativeModules(ReactApplicationContext context) {
        return Arrays.asList(new ExoPlayerModule(context));
    }

    @Override
    public List<ViewManager> createViewManagers(ReactApplicationContext context) {
        return Arrays.asList(new ExoPlayerViewManager());
    }
}

